using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The MCP SDK discovers tools by scanning for [McpServerToolType] classes
/// and [McpServerTool] methods. Tool/parameter descriptions flow to the LLM
/// via [Description] attributes.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor-injected HttpClient — the MCP SDK resolves this from the DI
    // container each time it invokes a tool on this class.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool("get_forecast")]
    [Description("Get the weather forecast for a city. Returns temperature and conditions.")]
    public async Task<string> GetForecastAsync(
        [Description("City name, e.g. 'Seattle'")] string city,
        [Description("Number of forecast days (1-5)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.weatherapi.com/v1/forecast.json?q={Uri.EscapeDataString(city)}&days={days}";
        var response = await _httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }

    [McpServerTool("get_alerts")]
    [Description("Get active weather alerts for a US state.")]
    public async Task<string> GetAlertsAsync(
        [Description("Two-letter US state code, e.g. 'WA'")] string state,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.weather.gov/alerts/active?area={Uri.EscapeDataString(state)}";
        var response = await _httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        var alerts = doc.RootElement.GetProperty("features")
            .EnumerateArray()
            .Select(f =>
            {
                var p = f.GetProperty("properties");
                return new
                {
                    Event = p.GetProperty("event").GetString(),
                    Area = p.GetProperty("areaDesc").GetString(),
                    Headline = p.GetProperty("headline").GetString()
                };
            });

        return JsonSerializer.Serialize(alerts, new JsonSerializerOptions { WriteIndented = true });
    }
}

